<?php requirePermission('reports');$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$st=$pdo->prepare("SELECT COUNT(*) qty,COALESCE(SUM(s.total-COALESCE(r.ret,0)),0) total FROM sales s LEFT JOIN (SELECT sale_id,SUM(total) ret FROM sale_returns GROUP BY sale_id) r ON r.sale_id=s.id WHERE s.status IN ('completed','partially_returned') AND DATE(s.created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$kpi=$st->fetch();$kpi['avg']=$kpi['qty']?$kpi['total']/$kpi['qty']:0;
$st=$pdo->prepare("SELECT sp.method payment_method,COUNT(DISTINCT s.id) qty,SUM(sp.amount) total FROM sale_payments sp JOIN sales s ON s.id=sp.sale_id WHERE s.status IN ('completed','partially_returned') AND DATE(s.created_at) BETWEEN ? AND ? GROUP BY sp.method ORDER BY total DESC");$st->execute([$from,$to]);$payments=$st->fetchAll();
$st=$pdo->prepare("SELECT p.name,SUM(si.quantity) qty,SUM(si.total) total,SUM((si.unit_price-p.cost)*si.quantity) gross_profit FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.status IN ('completed','partially_returned') AND DATE(s.created_at) BETWEEN ? AND ? GROUP BY p.id,p.name ORDER BY qty DESC LIMIT 10");$st->execute([$from,$to]);$tops=$st->fetchAll();
$returns=$pdo->prepare("SELECT COALESCE(SUM(total),0) FROM sale_returns WHERE DATE(created_at) BETWEEN ? AND ?");$returns->execute([$from,$to]);$returnsTotal=$returns->fetchColumn();
$low=$pdo->query("SELECT name,sku,stock,min_stock FROM products WHERE active=1 AND stock<=min_stock ORDER BY stock ASC")->fetchAll();$title='Relatórios';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Relatórios gerenciais</h1><p>Faturamento líquido, devoluções, pagamentos e estoque.</p></div></div><section class="panel"><form class="filters"><label>De<input type="date" name="from" value="<?=e($from)?>"></label><label>Até<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Atualizar</button></form></section><div class="cards"><div class="stat"><small>Faturamento líquido</small><strong><?=money($kpi['total'])?></strong></div><div class="stat"><small>Vendas válidas</small><strong><?=$kpi['qty']?></strong></div><div class="stat"><small>Ticket médio</small><strong><?=money($kpi['avg'])?></strong></div><div class="stat"><small>Devoluções/estornos</small><strong><?=money($returnsTotal)?></strong></div></div><div class="grid two"><section class="panel"><h2>Por forma de pagamento</h2><table><thead><tr><th>Forma</th><th>Vendas</th><th>Total líquido</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=e(paymentLabel($p['payment_method']))?></td><td><?=$p['qty']?></td><td><?=money($p['total'])?></td></tr><?php endforeach;?></tbody></table></section><section class="panel"><h2>Produtos mais vendidos</h2><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Receita</th><th>Margem bruta*</th></tr></thead><tbody><?php foreach($tops as $p):?><tr><td><?=e($p['name'])?></td><td><?=$p['qty']?></td><td><?=money($p['total'])?></td><td><?=money($p['gross_profit'])?></td></tr><?php endforeach;?></tbody></table><small>*Estimativa pelo custo atual cadastrado.</small></section></div><section class="panel"><h2>Produtos para reposição</h2><table><thead><tr><th>Produto</th><th>SKU</th><th>Atual</th><th>Mínimo</th></tr></thead><tbody><?php foreach($low as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['sku'])?></td><td><span class="badge danger"><?=$p['stock']?></span></td><td><?=$p['min_stock']?></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/../../includes/footer.php';?>
